// 旧版 (Phase 4-1)。中身は現行版と同じで、assets.json だけが別の実体を指す。
// 「同じ cat.png が版によって別の blob になる」ことを確かめるための種。
const assigned = new Image();
assigned.id = "assigned";
assigned.onload = () => {
  assigned.dataset.width = String(assigned.naturalWidth);
  document.body.append(assigned);
};
assigned.src = "cat.png";
